import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person in a pool with their share percent (two decimals); retired when the person has a retirement date set. */
export type PoolMember = { person: number; name: string; share: string; retired: boolean };

/** A pool: its members, the total of their shares (a retired member's counting 0.00), and whether that is 100.00. */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

export const poolsKey = (sheet: string) => ['pools', sheet] as const;

export const poolsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/pools`;

export const poolMembersPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/pool-members`;

/** The sheet's pools, in the order added. */
export function usePools(sheet: string) {
  return useQuery({
    queryKey: poolsKey(sheet),
    queryFn: () => getJson<Pool[]>(poolsPath(sheet)),
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { usePeople } from '../people/people';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { poolMembersPath, poolsKey, poolsPath, usePools, type Pool } from './pools';

// One pool's row: its members with their shares, its total share and whether it is balanced, and a form that adds
// a member chosen from the sheet's people.
function PoolRow({ sheet, user, pool }: { sheet: string; user: string; pool: Pool }) {
  const queryClient = useQueryClient();
  const { data: people = [] } = usePeople(sheet);
  const [person, setPerson] = useState('');
  const [share, setShare] = useState('');

  const add = useMutation({
    mutationFn: (body: { pool: string; person: number | null; share: string }) =>
      postJson<Pool[]>(byUser(poolMembersPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(poolsKey(sheet), updated);
      setPerson('');
      setShare('');
    },
  });
  const send = useSubmitOnce(add);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a person already in the pool or a bad share.
    send({ pool: pool.name, person: person === '' ? null : Number(person), share });
  };

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong> — total share <span data-testid="pool-total-share">{pool.totalShare}</span>,
      balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li key={m.person} data-testid={`pool-member-${pool.name}-${m.person}`}>
            {m.name} <span data-testid="pool-share">{m.share}</span>%{m.retired ? ' (retired)' : ''}
          </li>
        ))}
      </ul>
      <form onSubmit={submit}>
        <select
          data-testid="pool-member-select"
          value={person}
          onChange={(e) => {
            setPerson(e.target.value);
            add.reset();
          }}
        >
          <option value="">Choose a person</option>
          {people.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
        </select>{' '}
        <label>
          Share %{' '}
          <input
            data-testid="pool-member-share"
            value={share}
            onChange={(e) => {
              setShare(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
          Add member
        </button>
        {add.isError && (
          <span data-testid="pool-error" role="alert">
            {' '}A member must not already be in the pool, and a share has two decimals, above 0.00 and at most 100.00.
          </span>
        )}
      </form>
    </li>
  );
}

// The sheet's pools, and a form that adds one.
function Pools({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: pools = [] } = usePools(sheet);
  const [name, setName] = useState('');

  const add = useMutation({
    mutationFn: (body: { name: string }) => postJson<Pool[]>(byUser(poolsPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(poolsKey(sheet), updated);
      setName('');
    },
  });
  const send = useSubmitOnce(add);

  const change = (next: string) => {
    setName(next);
    add.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a blank name or one already a pool.
    send({ name });
  };

  return (
    <section>
      <h2>Pools</h2>
      <form onSubmit={submit}>
        <label>
          Name <input data-testid="pool-form-name" value={name} onChange={(e) => change(e.target.value)} />
        </label>{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {add.isError && (
          <span data-testid="pool-form-error" role="alert">
            {' '}A pool's name must not be blank nor already a pool.
          </span>
        )}
      </form>
      <ul>
        {pools.map((p) => (
          <PoolRow key={p.name} sheet={sheet} user={user} pool={p} />
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 9.8, Component: Pools });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { hundredths } from '../rates/rates';

/** The sheet's settings: the clerk limit with two decimals, the most due a clerk may settle ('' for no limit);
 *  the floor with two decimals, the least a claim's live due is; and the terms, the whole days after its date by
 *  which a claim is due; and the late percent with two decimals, charged on an overdue claim's figure for every
 *  full 30 days it is overdue; and the policy date (yyyy-MM-dd; '' for the sheet's today): a claim dated before it
 *  rounds half up, on or after it half to even; and the period numbering from-date (yyyy-MM-dd; '' for off): while
 *  the sheet's today is on or after it, a claim opened is numbered within its period; and each grade's own terms
 *  (whole days; '' when it takes the sheet's terms), from which a claim's due-by is fixed when it is added; and the
 *  cap with two decimals, the most a person's due-total is ('' for no cap). Each is the value in force on the sheet's
 *  today. And each action's permitted roles in the permission matrix (comma separated; '' for its standing rule). And the
 *  grace days (whole days; '' for off): a today change closes each open period whose to-date plus them is before it.
 *  And the entry date (yyyy-MM-dd; '' for off): while set, a new claim's date defaults to it instead of the sheet's today.
 *  And each grade's grace (whole days; '' for none), in force on the sheet's today: a claim whose person's grade in
 *  force on its date has a grace in force on that date is overdue only once its due-by plus the grace is before the
 *  sheet's today, and its late charge's 30-day boundaries are counted from there.
 *  And each grade's own proof threshold (two decimals; '' for none), in force on the sheet's today: a claim whose
 *  person's grade in force on its date has one in force on that date takes it in place of the sheet's.
 *  And, for each dated key (every one that carries a figure), its values as recorded, by from-date. */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string; policyDate: string; periodNumberingFrom: string;
  termsA: string; termsB: string; termsC: string; cap: string;
  proofThreshold: string; noteThreshold: string; graceDays: string; entryDate: string; graceA: string; graceB: string; graceC: string;
  proofThresholdA: string; proofThresholdB: string; proofThresholdC: string; perms: Partial<Record<PermAction, string>>; dated: Partial<Record<SettingKey, DatedValue[]>> };

/** A dated setting's value as recorded: in force from its from-date (yyyy-MM-dd). */
export type DatedValue = { from: string; value: string };

/** A figure in force by date (yyyy-MM-dd), in hundredths. */
export type DatedCents = (date: string) => bigint;

/** Whether a setting is dated: every one that carries a figure is; the policy, period numbering and entry dates and the grace days are not. */
export function isDated(key: SettingKey): boolean {
  return key !== 'policy-date' && key !== 'period-numbering-from' && key !== 'grace-days' && key !== 'entry-date' && !key.startsWith('perm-');
}

/** The figure in force on a date: the value of the latest from-date on or before it, before every from-date (or
 *  where a blank is in force) the starting value. */
function datedCents(values: DatedValue[] | undefined, start: string): DatedCents {
  const sorted = [...(values ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  return (date) => {
    let value = start;
    for (const v of sorted) {
      if (v.from > date) break;
      value = v.value === '' ? start : v.value;
    }
    return hundredths(value);
  };
}

/** A setting's key as the server names it, with the field of {@link Settings} that shows it. */
export type SettingKey = 'clerk-limit' | 'floor' | 'terms' | 'late-pct' | 'policy-date' | 'period-numbering-from'
  | 'terms-A' | 'terms-B' | 'terms-C' | 'grace-A' | 'grace-B' | 'grace-C' | 'proof-threshold-A' | 'proof-threshold-B' | 'proof-threshold-C' | 'cap' | 'proof-threshold' | 'note-threshold' | 'grace-days' | 'entry-date' | `perm-${PermAction}`;

/** The actions whose roles the permission matrix sets, each with its standing rule (used while its entry is blank). */
export const PERMISSIONS = [
